envAreaNo:['區域編號','Area number','Número de área','Mã khu vực'],envArea:['區域名稱','Area name','Nombre del área','Tên khu vực'],envContent:['內容','Content','Contenido','Nội dung'],envFrequency:['次數','Frequency','Frecuencia','Tần suất'],envTime:['清掃時間','Cleaning time','Horario de limpieza','Thời gian vệ sinh'],envResponsible:['負責人','Person in charge','Responsable','Người phụ trách'],envStatus:['查核狀況','Audit status','Estado de verificación','Tình trạng kiểm tra'],envNote:['備註','Note','Nota','Ghi chú'],
